 const actions=el('div',null,'mh-actions');const save=button('Save to library',async()=>{save.disabled=true;try{await post('/media/library',{item});save.textContent='Saved to library';message('Saved to your library')}catch(e){message(e)}finally{save.disabled=false}});save.prepend(uiIcon('plus'));actions.append(save,button('Remove from library',async()=>{try{await post('/media/library',{item,action:'remove'});save.replaceChildren(uiIcon('plus'),doc.createTextNode('Save to library'));message('Removed from your library')}catch(e){message(e)}},'mh-button mh-subtle'));if(item.transferHash)actions.append(button('Play downloaded files',async()=>{try{await post('/torrents',{action:'restore'},engine);await post('/torrents',{action:'resume',hash:item.transferHash,title:item.title},engine);waitForFiles(item.transferHash,item.title)}catch(e){message(e)}},'mh-button mh-primary'));info.append(actions);hero.append(info);body.append(hero);root.scrollTop=0;const heading=info.querySelector('h1');heading.tabIndex=-1;heading.focus({preventScroll:true});
