  const h=el('h2','Episodes');body.append(h);status.textContent='Loading episodes…';try{const eps=await request('/media/episodes?id='+encodeURIComponent(item.id));if(id!==renderId)return;status.textContent=eps.length+' episodes';const grid=el('div',null,'mh-episodes');for(const ep of eps)grid.append(button(ep.number+' · '+ep.title,()=>animePlay(item,ep)));body.append(grid)}catch(e){message(e)}return;
