async function play(url,title,subtitles=[],options={}){
 if(typeof win.SeanimeNativePlayerMessage!=='function'){message('The Seanime player is still loading. Try Play again in a moment.');return}
 try{
  message('Preparing playback…');
  const subtitleTracks=subtitles.map((sub,index)=>{
   const language=sub.language||sub.lang||'und',track={index,label:sub.label||sub.name||language,language,type:sub.type||sub.format||'srt',default:sub.default??language==='ar',useLibassRenderer:sub.useLibassRenderer??true};
   if(sub.content!==undefined)track.content=sub.content;
   else if(sub.src)track.src=sub.src;
   else if(sub.url){track.src=api+'/media/subtitle-file?url='+encodeURIComponent(sub.url);track.type='vtt'}
   return track;
  });
  if(typeof win.SeanimeNativePlayerMessage!=='function')throw Error('The Seanime player is unavailable. Open the player again.');
  let decoded=url;try{decoded=decodeURIComponent(url)}catch{}
  const hls=/\.m3u8(?:[?#&]|$)/i.test(decoded),mimeType=options.mimeType||(hls?'application/vnd.apple.mpegurl':/\.webm(?:[?#&]|$)/i.test(decoded)?'video/webm':'video/mp4');
  const info={id:'media-hub-'+Date.now()+'-'+Math.random().toString(36).slice(2),streamType:'url',streamPath:title,streamUrl:url,mimeType,contentLength:options.contentLength||0,subtitleTracks,isNakamaWatchParty:false};
  win.SeanimeNativePlayerMessage({type:'open-and-await',payload:'Loading '+title+'…'});
  win.SeanimeNativePlayerMessage({type:'watch',payload:info});message('');
 }catch(e){message(e)}
}
async function animePlay(item,ep){message('Loading episode source…');try{const source=await request('/media/anime-stream?'+new URLSearchParams({id:item.id,episode:ep.id}));message('');play(api+'/media/proxy?url='+encodeURIComponent(source.url),item.title+' · Episode '+ep.number,source.subtitles)}catch(e){message(e)}}
