 const poll=async()=>{if(id!==renderId||root.hidden)return;try{const items=await request('/torrents',{},engine);if(id!==renderId)return;list.replaceChildren();tabCount('downloads',items.length);status.textContent=items.length?items.length+' transfers':'No active transfers';for(const t of items){const row=el('div',null,'mh-release'),info=el('div');info.append(el('strong',t.title),el('p',t.error||[(t.progress*100).toFixed(1)+'%',Math.round(t.downloadSpeed/1024)+' KiB/s',t.peers+' peers',t.mode==='download'?'Downloading':'Streaming'].join(' · ')));const progress=el('progress');progress.max=1;progress.value=t.progress;info.append(progress);const actions=el('div',null,'mh-actions');actions.append(button('Play',()=>waitForFiles(t.hash,t.title)),button('Stop',async()=>{try{await post('/torrents',{action:'stop',hash:t.hash},engine);poll()}catch(e){message(e)}}));row.append(info,actions);list.append(row)}}catch(e){message(e)}pollTimer=setTimeout(poll,2000)};await poll();
