let registryPromise,sourceDialog,nativePlayerAvailable=false,nativeReturnToHub=false,sourcePreferences,preferencesPromise;
const sourceKey=source=>source.nativeId||'site:'+source.id;
const sourceEnabled=source=>source.mode!=='unavailable'&&!(sourcePreferences?.disabledSourceIds||[]).includes(source.id);
const loadSourcePreferences=()=>preferencesPromise||=(request('/media/source-preferences').then(value=>sourcePreferences=value).catch(e=>{preferencesPromise=null;throw e}));
async function discoverSources(kind){const [data]=await Promise.all([sourceRegistry(),loadSourcePreferences()]);return data.sources.filter(x=>x.kinds.includes(kind)&&sourceEnabled(x)).sort((a,b)=>Number(!a.nativeId)-Number(!b.nativeId)||a.name.localeCompare(b.name))}
async function setSourceEnabled(source,enabled){const value=await post('/media/source-preferences',{id:source.id,enabled});sourcePreferences=value;preferencesPromise=Promise.resolve(value);if(!enabled&&state.provider===sourceKey(source)){const choices=await discoverSources(state.kind);state.provider=choices.length?sourceKey(choices[0]):'';state.page=1;state.scroll=0}return value}

